try:
    xrange(1)
except:
    xrange = range

def array_overwrite(source, s_start, dest, d_start, length):
    dest[d_start:d_start + length] = source[s_start:s_start + length]

def blockxor(source, s_start, dest, d_start, length):
    for i in xrange(length):
        dest[d_start + i] ^= source[s_start + i]

def R(X, destination, a1, a2, b):
    a = (X[a1] + X[a2]) & 0xffffffff
    X[destination] ^= ((a << b) | (a >> (32 - b)))

def salsa20_8(B):
    x = B[:16]

    for i in xrange(4):
        R(x, 4, 0,12, 7);R(x, 8, 4, 0, 9);R(x,12, 8, 4,13);R(x, 0,12, 8,18)
        R(x, 9, 5, 1, 7);R(x,13, 9, 5, 9);R(x, 1,13, 9,13);R(x, 5, 1,13,18)
        R(x,14,10, 6, 7);R(x, 2,14,10, 9);R(x, 6, 2,14,13);R(x,10, 6, 2,18)
        R(x, 3,15,11, 7);R(x, 7, 3,15, 9);R(x,11, 7, 3,13);R(x,15,11, 7,18)
        R(x, 1, 0, 3, 7);R(x, 2, 1, 0, 9);R(x, 3, 2, 1,13);R(x, 0, 3, 2,18)
        R(x, 6, 5, 4, 7);R(x, 7, 6, 5, 9);R(x, 4, 7, 6,13);R(x, 5, 4, 7,18)
        R(x,11,10, 9, 7);R(x, 8,11,10, 9);R(x, 9, 8,11,13);R(x,10, 9, 8,18)
        R(x,12,15,14, 7);R(x,13,12,15, 9);R(x,14,13,12,13);R(x,15,14,13,18)

    for i in xrange(16):
        B[i] = (x[i] + B[i]) & 0xffffffff

def blockmix_salsa8(BY, Yi, r):
    start = (2 * r - 1) * 16
    X = BY[start:start+16]

    for i in xrange(2 * r):
        blockxor(BY, i * 16, X, 0, 16)
        salsa20_8(X)
        array_overwrite(X, 0, BY, Yi + (i * 16), 16)

    for i in xrange(r):
        array_overwrite(BY, Yi + (i * 2) * 16, BY, i * 16, 16)
        array_overwrite(BY, Yi + (i*2 + 1) * 16, BY, (i + r) * 16, 16)

def smix(B, Bi, r, N, V, X):
    array_overwrite(B, Bi, X, 0, 32 * r)

    for i in xrange(N):
        array_overwrite(X, 0, V, i * (32 * r), 32 * r)
        blockmix_salsa8(X, 32 * r, r)

    for i in xrange(N):
        j = X[(2 * r - 1) * 16] & (N - 1)
        blockxor(V, j * (32 * r), X, 0, 32 * r)
        blockmix_salsa8(X, 32 * r, r)

    array_overwrite(X, 0, B, Bi, 32 * r)

from numpy import *
import sys

TEXT = '.123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
NUMBER = arange(len(TEXT)+1)

## Read the file in
def read(name):
    with open(name) as fid:
        str = fid.read().replace('\n',"")
    s = int(sqrt(len(str)))

    # check input
    if s != int(sqrt(s))**2:
        raise Exception("Input needs to be quadratic")

    if len(str.strip(TEXT[0:s + 1])) != 0:
        raise Exception("Do not use anything beside %s with this base" % TEXT[0:s + 1])
    return (str,s)

## Set the value in field and adjust the possibility tensor
def set(col,row,wert,feld,pos,s):
    if feld[col,row] != 0:
        raise Exception

    pos[col,row,:] = 0
    pos[:,row,wert] = 0
    pos[col,:,wert] = 0

    ss = int(sqrt(s))

    col_start = col // ss * ss
    row_start = row // ss * ss
    pos[col_start:col_start + ss,row_start:row_start + ss,wert] = 0

    feld[col,row] = wert + 1

## Read in the stuff and create field
def read_and_construct(name):
    str,s = read(name)
    feld = zeros((s,s),dtype=uint8)
    pos = ones((s,s,s),dtype=bool_)

    for ind in range(s**2):
        if str[ind] is not '0' and str[ind] is not '.':
            set(ind // s,ind % s,NUMBER[TEXT.index(str[ind])] - 1,feld,pos,s)
    return (feld,pos,s)

## Write the output into a file
def write(name,feld,s):
    with open(name,'w') as fid:
        for col in range(s):
            for row in range(s):
                fid.write(TEXT[feld[col,row]])
            fid.write('\n')

## Are we there yet?
def done(feld,s):
    return count_nonzero(feld) == s**2

## Start the Analytical Process returns 0 if solved
def anal(feld,pos,s):
    neu = 1
    while neu:
        neu = 0

        # Scan all dimensions of pos 
        ind = where(sum(pos,axis = 2) == 1)
        for x,y in zip(ind[0],ind[1]):      
            set(x,y,nonzero(pos[x,y,:])[0][0],feld,pos,s)

        ind = where(sum(pos,axis = 1) == 1)
        for x,y in zip(ind[0],ind[1]):      
            set(x,nonzero(pos[x,:,y])[0][0],y,feld,pos,s)

        ind = where(sum(pos,axis = 0) == 1)
        for x,y in zip(ind[0],ind[1]):      
            set(nonzero(pos[:,x,y])[0][0],x,y,feld,pos,s)   

        # get the box
        for x in range(s):
            for y in range(s):
                col_start = x // s * s
                row_start = x % s * s

                if sum(pos[col_start:col_start + s,row_start:row_start + s,y]) == 1:
                    ind = nonzero(pos[col_start:col_start + s,row_start:row_start + s,y]);
                    neu = set(col_start + ind[0][0],row_start + ind[1][0],y,feld,pos,s)

## A brute force method to calculate the missing values returns 0 if solved
def brute(feld,pos,s):
    # get a starting point with minimum possibilities
    n_pos = sum(pos,axis=2)
    n_pos[n_pos == 0] = 255
    ind = unravel_index(n_pos.argmin(), n_pos.shape)

    # trial and error
    for wert in nonzero(pos[ind[0],ind[1],:])[0]:   
        try_feld = copy(feld)
        try_pos = copy(pos)

        try:
            set(ind[0],ind[1],wert,try_feld,try_pos,s)
            anal(try_feld,try_pos,s)

            if not done(try_feld,s):
                try_feld, try_pos = brute(try_feld,try_pos,s)

            if done(try_feld,s):
                break
        except:
            pass
    return (try_feld, try_pos)

## main method
if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise Exception("Give path to input and output file")

    feld, pos, s = read_and_construct(sys.argv[1])
    anal(feld,pos,s)

    if not done(feld,s):
        feld,pos = brute(feld,pos,s)

    write(sys.argv[2],feld,s)

Node = collections.namedtuple('Node', 'fact_id person_ids names')

def grouped(neighborhood):
    """takes a flat set of nodes and returns the connected subsets"""
    seen = set()
    def component(node):
        unseen_nodes = set((node,))
        while unseen_nodes:
            node = unseen_nodes.pop()
            seen.add(node)
            unseen_nodes |= adjacent(node, neighborhood) - seen
            yield node
    return (set(component(node)) for node in neighborhood if node not in seen)

def adjacent(a, n):
    """returns all elements of n(eighborhood) adjacent to a(ctive node)"""
    return {e for e in n if a.person_ids & e.person_ids or a.names & e.names}

#!/usr/bin/env python

import numpy as np
from copy import copy
from abc import ABCMeta, abstractmethod

class Connect4Game():
    def __init__(self, player1, player2):
        self.player1 = player1
        self.player2 = player2
        self.player_names = {player1 : "Player1", player2 : "Player2"}
        self.board = np.zeros((6, 7), dtype=np.int8)
        self.turn = player1
        self.last_move = ()
        self.winner = None

    def gameover(self):
        if self.last_move == ():
            return False

        rind, cind = self.last_move

        row = self.board[rind, :]
        col = self.board[:, cind]
        diag1 = np.diagonal(self.board, cind - rind)
        diag2 = np.diagonal(np.fliplr(self.board), -(cind + rind - 6))

        for line in [row, col, diag1, diag2]:
            if line.shape[0] < 4:
                continue

            for four in [line[i:i+4] for i in range(len(line)-3)]:
                if sum(four == 1) == 4:
                    self.winner = self.player1
                    return True
                elif sum(four == 2) == 4:
                    self.winner = self.player2
                    return True

        if sum(self.board[0] == 0) == 0:
            return True

        return False

    def move(self, cind):
        free_index = sum(self.board[:, cind] == 0) - 1
        if free_index == -1:
            return False

        if self.turn is self.player1:
            self.board[free_index, cind] = 1
            self.turn = self.player2
        else:
            self.board[free_index, cind] = 2
            self.turn = self.player1

        self.last_move = (free_index, cind)
        return True

    def play(self):
        while not self.gameover():
            print(self.board)
            print(self.player_names[self.turn]+"'s turn.")

            self.move(self.turn.get_move(copy(self.board)))

        print(self.board)

        if self.winner is self.player1:
            print("Winner: player1")
        elif self.winner is self.player2:
            print("Winner: player2")
        else:
            print("Tie")

class BasePlayer(metaclass=ABCMeta):
    @abstractmethod
    def __init__(self, empty, me, opponent):
        pass

    @abstractmethod
    def get_move(self, board):
        pass

class HumanPlayer(BasePlayer):
    def __init__(self, empty, me, opponent):
        pass

    def get_move(self, board):
        col = input("Your move (0-6): ")
        return int(col)

class RandomPlayer(BasePlayer):
    def __init__(self, empty, me, opponent):
        pass

    def get_move(self, board):
        free_columns = np.where(board[0] == 0)[0]
        return np.random.choice(free_columns)

def main():
    player1 = HumanPlayer(0, 1, 2)
    player2 = RandomPlayer(0, 2, 1)

    game = Connect4Game(player1, player2)
    game.play()

if __name__ == "__main__":
    main()

def _contains(subseq, inseq):
    return any(inseq[pos:pos + len(subseq)] == subseq for pos in range(0, len(inseq) - len(subseq) + 1))

def lcss(s1, s2, threshold=3):

    all_of = []

    def is_inner_seq(i, j):
        return any(k < i < j <= l or k <= i < j < l for k, l in all_of)

    for i in range(0, len(s1)):
        for j in range(i + threshold, len(s1) + 1):

            if _contains(subseq=s1[i:j], inseq=s2):
                all_of.append((i, j))  # add a tuple to work OK when s1, s2 are lists

    only_outer_seq = filter(lambda tup: not is_inner_seq(tup[0], tup[1]),
                            all_of)

    return [s1[i:j] for i, j in only_outer_seq]

