OPENING_BRACKETS = {"{", "[", "("}
BRACKETS_MAP = {"]": "[", "}": "{", ")": "("}

def isValid(s):
    stack = []
    for bracket in s:
        if bracket in OPENING_BRACKETS:
            stack.append(bracket)
        elif not stack:
            return False        # Can't pop from an empty stack
        elif stack.pop() != BRACKETS_MAP[bracket]:
            return False        # Closing the wrong kind of bracket
    return not stack

def rhyme_map(rules, word_suffix_len=3):
    words = set(chain.from_iterable(chain.from_iterable(rules.values())))
    abbreviations = {}
    for word in words:
        for suffix_len in range(1, len(word)):
            suffix = word[-suffix_len:]
            if suffix in words:
                 abbreviations[word] = suffix
                 break
    return abbreviations

def __contains__(self,value):
    """
    Returns True or False depending on whether an item with
    node.value = value is in the list
    """
    current = self.head
    found = False
    while current and not found:
        if current.value == value:
            found = True
            return True
        else:
            current = current.next
    if not current:
        return False

