    d = dict()
    for [part, subpart] in parts_h:
        if part in d:
            d[part].append(subpart)
        else:
            d[part] = [subpart]

    # add start elements to bom, which later will be removed
    bom = [[serial, None, part, part] for [serial, part] in order]
    i = 0
    # treat it as a queue, adding to it while looping
    while i < len(bom):
        [serial, parent, part, path] = bom[i]
        i += 1
        if part in d:
            for subpart in d[part]:
                bom.append([serial, part, subpart, path + '/' + subpart])
        elif i < len(order): # when there are no sub parts
            bom.append([serial, part, None, path])

    # return the part without the starter elements
    return bom[len(order):]

def __str__(self):
    """Return formatted grid."""
    BOLD = '\033[1m'
    ENDC = '\033[0m'

    fill_mask = np.sum(self.mask, axis=2) == 1

    top_line = '┏' + ('━━┯' * 2 + '━━┳') * 2 + '━━┯' * 2 + '━━┓'
    mid_line = '┣' + ('━━┿' * 2 + '━━╋') * 2 + '━━┿' * 2 + '━━┫'
    bot_line = '┗' + ('━━┷' * 2 + '━━┻') * 2 + '━━┷' * 2 + '━━┛'
    div_line = '┠' + ('──┼' * 2 + '──╂') * 2 + '──┼' * 2 + '──┨'
    num_line = '┃ {}│ {}│ {}' * 3 + '┃'

    counter = 1
    lines = [top_line]
    for row_index, row in enumerate(self.grid):
        line_to_print = []
        for col_index, cell in enumerate(row):
            if fill_mask[row_index, col_index] == 1:
                line_to_print.append(BOLD + str(cell) + ENDC)
            elif cell == 0:
                line_to_print.append(' ')
            else:
                line_to_print.append(str(cell))
        lines.append(num_line.format(*line_to_print))
        if (counter % 3 == 0) and counter < 9:
            lines.append(mid_line)
        elif counter < 9:
            lines.append(div_line)
        counter += 1
    lines.append(bot_line)
    return "\n".join(lines)

