def travel(self):
    "Returns a python function that reflect the tree of self"

    #if function type is a simple number return a function that returns it
    if(type(self.function)==type(1.0) or type(self.function)==type(1)):
        def actual_function(**kargs):
            return self.function

    elif(type(self.function)==type(' ')):

        #if the function contains [ and ] assume its a subscripted variable
        if('[' in self.function and ']' in self.function):
            var_name=self.function.split('[')[0]
            var_index=int(self.function.split('[',1)[1][:-1])
            def actual_function(**kargs):
                #the variables index "picked" from the list in the user arguments
                return kargs[var_name][var_index]

        else:
            #other wise return a function that returns its variable "picked" from the user arguments
            def actual_function(**kargs):
                return kargs[self.function]

    else:
        #return a function that returns the value of this nodes function using the leaves as arguments
        function_list=list(map(lambda x: x.travel(), self.leaves))
        def actual_function(**kargs):
            return self.function(* [x(**kargs) for x in function_list] )

        # def actual_function(**kargs):
        #     return self.function(* list(map(lambda x: x.travel()(**kargs), self.leaves)) )

    #return the function that we determined in the previous step
    return actual_function

class Card:
    """A card of a puzzle carries four symbol halfs."""

    def __init__(self, nr: int, n: SymbolHalf, w: SymbolHalf, s: SymbolHalf, o: SymbolHalf) -> None:
        """
        :param int nr: number of the card
        :param SymbolHalf n: northern symbol half
        :param SymbolHalf s: southern symbol half
        :param SymbolHalf w: western symbol half
        :param SymbolHalf o: eastern symbol half
        """
        assert isinstance(nr, int)
        self.nr = nr
        self.__symbole = [n, o, s, w]

    def __str__(self) -> str:
        return str(self.nr)

    def __getsymbolhalf(self, position: int, alpha: int) -> SymbolHalf:
        """
        get the symbol half in 'position' of the card accounting for the rotation 'alpha' of the card.
        :param int position: cardinal direction
        :param int alpha: rotation angle of the card 0 90 180 270
        :return: the requested symbol half
        """
        return self.__symbole[(alpha // 90 + position) % 4]

    def north(self, alpha: int) -> SymbolHalf:
        return self.__getsymbolhalf(0, alpha)

    def east(self, alpha: int) -> SymbolHalf:
        return self.__getsymbolhalf(1, alpha)

    def south(self, alpha: int) -> SymbolHalf:
        return self.__getsymbolhalf(2, alpha)

    def west(self, alpha: int) -> SymbolHalf:
        return self.__getsymbolhalf(3, alpha)

from __future__ import division

from itertools import combinations

def strange_div(lhs, rhs):
    if -0.0001 < rhs < 0.0001:
        return 100000
    else:
        return lhs / rhs

def do_op(op, lhs, rhs):
    if op == '+':
        return lhs + rhs
    elif op == '*':
        return lhs * rhs
    elif op == '-':
        return lhs - rhs
    elif op == '^':
        return rhs - lhs
    elif op == '/':
        return strange_div(lhs, rhs)
    elif op == '%':
        return strange_div(rhs, lhs)
    raise ValueError("Unknown operator: {!r}".format(op))

def compute_step(operands, x_idx, y_idx, method, op):
    method.append((operands[x_idx], op, operands[y_idx]))
    new_operands = [num for x, num in enumerate(operands) if x != x_idx and x != y_idx]
    new_operands.append(do_op(op, operands[x_idx], operands[y_idx]))
    return new_operands

def find_close_calculations(operands, method):
    if len(operands) == 1:
        return 23.9999 < operands[0] < 24.0001

    pairs = set()
    for (i, lhs), (j, rhs) in combinations(enumerate(operands), 2):
        tmp_key = tuple(sorted((lhs, rhs)))
        if tmp_key in pairs:
            continue
        pairs.add(tmp_key)

        for op in '+', '-', '*', '/', '^', '%':
            stepped = compute_step(operands, i, j, method, op)
            if find_close_calculations(stepped, method):
                print(str(method))
            method.pop()

def emit(self):
    buf = self.buf
    if buf:
        # skip \n if previous buffer ended with \r
        if self.carry_cr and buf.startswith(b'\n'):
            del buf[0]
        self.carry_cr = False

    lines = buf.splitlines()
    if buf:
        if self.is_open and not buf.endswith((b'\r', b'\n')):
            buf = lines.pop()
        else:
            if buf.endswith(b'\r'):
                self.carry_cr = True
            del buf[:]
    self.buf = buf

    self.emitted_this_cycle = False
    if lines:
        self.emitted_this_cycle = True
        for line in lines:
            yield (self.fd, line.decode(self.enc).rstrip())
    if not self.is_open:
        self.emitted_this_cycle = True
        yield (self.fd, None)

def parse_midi(self):
    ld = dict(on_notes = {},
              time = 0,
              previous_pitch = -1,
              delta = 0,
              tempos = []
             )

    dispatch = dict(
                    set_tempo=self.__set_tempo,
                    time_signature=self.__time_sign,
                    note_on=self.__note_on_off,
                    note_off=self.__note_on_off
                   )

    for message in self.track_in:
        try:
            dispatch[message.type](message,ld)
        except KeyError:
            print('Unkdown message type {0}'.format(message.type))
            sys.exit(1)                                                         

    # some tracks might be aempty in a midi file. For example they might contain comments as track name, and no note events
    if len(self.pitches.src_events) == 0:
        print("There are no note events in track {}!\n"
              "The file has {} tracks. Please try another one.".format(self.selected_track, self.num_tracks))
        exit(1)
    # a midi file might not contain tempo information at all. if it does, we calculate the average
    # else we just assign a default tempo of 120 bpm
    try:
        self.average_tempo = int(sum(ld['tempos']) / len(ld['tempos']))
    except ZeroDivisionError:
        self.average_tempo = mido.bpm2tempo(120)

import string
def meet_pattern(s):
    s = list(s)
    pattern = string.ascii_lowercase + ' '
    return all(pattern[i] in s for i in range(1, len(pattern)))

