        if not event_due:
            continue
        cal_event = Event()
        cal_event.begin = event_due
        cal_event.name = str(task)

        task_first_calendar = task.first_calendar

        if task_first_calendar == "":
            general_cal.events.append(cal_event)
        if task_first_calendar == "chores":
            chores_cal.events.append(cal_event)
        if task_first_calendar == "announcements":
            ann_cal.events.append(cal_event)


    with open(os.path.expanduser(ics_calendar_full_path), 'w') as f:
        f.writelines(general_cal)

    with open(os.path.expanduser(ics_calendar_full_path_chores), 'w') as f:
        f.writelines(chores_cal)

    with open(os.path.expanduser(ics_calendar_full_path_announcements), 'w') as f:
        f.writelines(ann_cal)

    sys.exit(0)

class TransparentProxy:
    def __init__(self, obj, props=None):
        object.__setattr__(self, '_object', obj)
        object.__setattr__(self, '_props', set(props or dir(obj)))

    def __getattribute__(self, name):
        _props = object.__getattribute__(self, '_props')
        if name in _props:
            _object = object.__getattribute__(self, '_object')
            return getattr(_object, name)
        else:
            return object.__getattribute__(self, name)

    def __setattr__(self, name, value):
        _props = object.__getattribute__(self, '_props')
        if name in _props:
            _object = object.__getattribute__(self, '_object')
            return setattr(_object, name, value)
        else:
            return object.__setattr__(self, name, value)

    def __delattr__(self, name):
        _props = object.__getattribute__(self, '_props')
        if name in _props:
            _object = object.__getattribute__(self, '_object')
            return delattr(_object, name)
        else:
            return object.__delattr__(self, name)


class Singleton(type):
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super(Singleton, cls).__call__(*args, **kwargs)
        else:
            cls._instances[cls].__init__(*args, **kwargs)
        return cls._instances[cls]


class Target(TransparentProxy, metaclass=Singleton):
    def __init__(self, prop):
        super().__init__(Prop(prop), ['prop'])

import binascii

def test4(key='a', target='3141592653'):
    """Return a string whose MD5 hexdigest starts with target. The search
    starts at the string key.

    """
    key = bytearray(key.encode('ascii'))
    key_indexes = range(len(key) - 1, -1, -1)
    target_digest = binascii.unhexlify(target)
    md5 = hashlib.md5
    a, z = b'az'
    while True:
        if md5(key).digest().startswith(target_digest):
            return key.decode('ascii')
        for i in key_indexes:
            key[i] += 1
            if key[i] > z:
                key[i] = a
                if i == 0:
                    key.append(a)
                    key_indexes = range(len(key) - 1, -1, -1)
            else:
                break

