def prefixLimit(limit, num):
    sumOfPrefix = 0
    prefix = [] 
    for i in num:
        if sumOfPrefix < limit:
            sumOfPrefix = sumOfPrefix + i
            prefix.append(i)
            if sumOfPrefix > limit:
                return prefix

