def count_cuboids(a, b, LIMIT):
    """Given a Pythagorean pair (a, b), return the number of cuboids (p, q, r)
    such that 1 <= p, q, r <= LIMIT and ????

    """
    counter = 0
    temp = b // 2 
    if temp >= LIMIT:
        return 0
    elif b < LIMIT:
        counter += (a // 2)
    if temp <= a:
        counter += (a - temp)
        if (a - temp) % 2 == 0:
            counter += 1
    return counter

import doctest

def egcd(a, b):
    """
    Meaningful description here...

    >>> egcd(4132, 434)
    (2, -48, 457)
    """

    if a == 0:
        return (b, 0, 1)

    g, y, x = egcd(b % a, a)
    return (g, x - (b // a) * y, y)



