def pyramid(height):
    FMT = '%3s'
    def row(r):
        right_half = [FMT % num for num in range(2, 2 + r)] + \
                     [FMT % ' ' for spc in range(2 + r, 1 + height)]
        return ''.join(list(reversed(right_half)) + # Mirrored right half
                       [FMT % 1] +                  # Center
                       right_half)                  # Right half
    return "\n".join([row(r) for r in range(height)])

