terms=0;
maxTerms=0;
maxTermsNum=0;
prevTerms = dict()
for x in range(1,1000000):
    i=int(x)
    while (i!=1):
        if i in prevTerms:
            terms += prevTerms[i]
            break
        terms+=1
        a = i >> 1
        b = i - (a << 1)
        if (b==0):
            i = a
        else:
            i=3*i+1
    if x not in prevTerms:
        prevTerms[x] = terms
    if (terms>maxTerms):
        maxTerms=terms
        maxTermsNum=x
        print(x)
    terms=0;
print("Biggest one: is %s." %maxTermsNum)
